('''      public function add(entity:Entity) : void\n      {\n         var x:int = entity.px / this.boxWidth;\n         var y:int = entity.py / this.boxHeight;\n         if(x < 0 || x >= this.cols || y < 0 || y >= this.rows)\n         {\n            return;\n         }\n         Vector.<Entity>(this.partitions[this.cols * y + x])[this.partitionSizes[this.cols * y + x]] = entity;\n         ++this.partitionSizes[this.cols * y + x];\n         if(x > 0)\n         {\n            Vector.<Entity>(this.partitions[this.cols * y + x - 1])[this.partitionSizes[this.cols * y + x - 1]] = entity;\n            ++this.partitionSizes[this.cols * y + x - 1];\n         }\n         if(y > 0)\n         {\n            Vector.<Entity>(this.partitions[this.cols * (y - 1) + x])[this.partitionSizes[this.cols * (y - 1) + x]] = entity;\n            ++this.partitionSizes[this.cols * (y - 1) + x];\n         }\n         if(y < this.rows - 1)\n         {\n            Vector.<Entity>(this.partitions[this.cols * (y + 1) + x])[this.partitionSizes[this.cols * (y + 1) + x]] = entity;\n            ++this.partitionSizes[this.cols * (y + 1) + x];\n         }\n         if(x < this.cols - 1)\n         {\n            Vector.<Entity>(this.partitions[this.cols * y + x + 1])[this.partitionSizes[this.cols * y + x + 1]] = entity;\n            ++this.partitionSizes[this.cols * y + x + 1];\n         }\n      }\n''','''      private function addToPartition(index:int, entity:Entity) : void\n      {\n         var size:int = this.partitionSizes[index];\n         if(size >= this.partitions[index].length)\n         {\n            this.partitions[index].length = size + 64;\n         }\n         this.partitions[index][size] = entity;\n         this.partitionSizes[index] = size + 1;\n      }\n      \n      public function add(entity:Entity) : void\n      {\n         var x:int = entity.px / this.boxWidth;\n         var y:int = entity.py / this.boxHeight;\n         if(x < 0 || x >= this.cols || y < 0 || y >= this.rows)\n         {\n            return;\n         }\n         var index:int = this.cols * y + x;\n         this.addToPartition(index,entity);\n         if(x > 0)\n         {\n            this.addToPartition(index - 1,entity);\n         }\n         if(y > 0)\n         {\n            this.addToPartition(index - this.cols,entity);\n         }\n         if(y < this.rows - 1)\n         {\n            this.addToPartition(index + this.cols,entity);\n         }\n         if(x < this.cols - 1)\n         {\n            this.addToPartition(index + 1,entity);\n         }\n      }\n''','dynamic partition add'),
('''      public function mapInArea(xs:Number, ys:Number, xe:Number, ye:Number, f:Function, includeWalls:Boolean = true) : void\n      {\n         var id:String = null;\n         var wall:Wall = null;\n         var y:int = 0;\n         var i:int = 0;\n''','''      public function mapInArea(xs:Number, ys:Number, xe:Number, ye:Number, f:Function, includeWalls:Boolean = true) : void\n      {\n         var wall:Wall = null;\n         var entity:Entity = null;\n         var entityId:int = 0;\n         var y:int = 0;\n         var i:int = 0;\n         ++this.visitStamp;\n''','map vars'),
