patch('com/brockw/stickwar/engine/StickWar.as',[
('''         this._spatialHash = new SpatialHash(this,this.map.width,this.map.height,50,this.map.height / 7,100);\n''','''         // Expansion battles can pack far more actors into one spatial bucket than vanilla.\n         this._spatialHash = new SpatialHash(this,this.map.width,this.map.height,50,this.map.height / 7,512);\n''','larger spatial buckets'),
('''         this.projectileManager.airEffects.splice(0,this.projectileManager.airEffects.length);\n''','''         this.projectileManager.airEffects.length = 0;\n''','clear air effects'),
('''      private function sortZ(dParent:DisplayObjectContainer, skip:int = 20) : void\n      {\n         var bFlipped:Boolean = false;\n         var o:int = 0;\n         skip = 1;\n         if(dParent.numChildren > 60)\n         {\n            skip = 10 + (dParent.numChildren - 60);\n         }\n         var isOdd:int = this.random.nextInt() % skip;\n         for(var i:int = dParent.numChildren - 1 - isOdd; i > 0; )\n         {\n            bFlipped = false;\n            for(o = 0; o < i; o++)\n            {\n               if(dParent.getChildAt(o) is Entity && dParent.getChildAt(o + 1) is Entity)\n               {\n                  if(Entity(dParent.getChildAt(o)).py > Entity(dParent.getChildAt(o + 1)).py)\n                  {\n                     dParent.swapChildrenAt(o,o + 1);\n                     bFlipped = true;\n                  }\n               }\n            }\n            if(!bFlipped)\n            {\n               return;\n            }\n            i -= skip;\n         }\n      }\n''','''      private function sortZ(dParent:DisplayObjectContainer, skip:int = 20) : void\n      {\n         // Two linear cocktail passes keep depth order converging without the old repeated bubble-sort scans.\n         var o:int = 0;\n         var left:Entity = null;\n         var right:Entity = null;\n         for(o = 0; o < dParent.numChildren - 1; o++)\n         {\n            if(dParent.getChildAt(o) is Entity && dParent.getChildAt(o + 1) is Entity)\n            {\n               left = Entity(dParent.getChildAt(o));\n               right = Entity(dParent.getChildAt(o + 1));\n               if(left.py > right.py)\n               {\n                  dParent.swapChildrenAt(o,o + 1);\n               }\n            }\n         }\n         for(o = dParent.numChildren - 1; o > 0; o--)\n         {\n            if(dParent.getChildAt(o - 1) is Entity && dParent.getChildAt(o) is Entity)\n            {\n               left = Entity(dParent.getChildAt(o - 1));\n               right = Entity(dParent.getChildAt(o));\n               if(left.py > right.py)\n               {\n                  dParent.swapChildrenAt(o - 1,o);\n               }\n            }\n         }\n      }\n''','linear depth sort'),
])

patch('com/brockw/stickwar/engine/projectile/ProjectileManager.as',[
('''      public function update(game:StickWar) : void\n      {\n         var i:int = 0;\n         var p:Projectile = null;\n         for(i = 0; i < this.projectiles.length; i++)\n         {\n            if(!Projectile(this.projectiles[i]).isInFlight())\n            {\n               p = this.projectiles.splice(i,1)[0];\n               p.framesDead = 0;\n               this._waitingToBeCleaned.push(p);\n            }\n            else\n            {\n               this.projectiles[i].update(game);\n            }\n         }\n         for(i = 0; i < this._waitingToBeCleaned.length; i++)\n         {\n            ++this._waitingToBeCleaned[i].framesDead;\n         }\n         while(this._waitingToBeCleaned.length != 0 && Boolean(this._waitingToBeCleaned[0].isReadyForCleanup()))\n         {\n            p = this._waitingToBeCleaned.shift();\n            if(game.battlefield.contains(p))\n            {\n               game.battlefield.removeChild(p);\n            }\n            this._projectileMap[p.type].returnItem(p);\n         }\n      }\n''','''      public function update(game:StickWar) : void\n      {\n         var i:int = 0;\n         var last:int = 0;\n         var p:Projectile = null;\n         // Swap-remove finished projectiles: no Array.splice compaction and no skipped successor.\n         i = 0;\n         while(i < this.projectiles.length)\n         {\n            p = Projectile(this.projectiles[i]);\n            if(!p.isInFlight())\n            {\n               last = this.projectiles.length - 1;\n               this.projectiles[i] = this.projectiles[last];\n               this.projectiles.pop();\n               p.framesDead = 0;\n               this._waitingToBeCleaned.push(p);\n            }\n            else\n            {\n               p.update(game);\n               ++i;\n            }\n         }\n         // Dead effects are independent; reclaim ready entries in-place instead of shifting the whole queue.\n         i = this._waitingToBeCleaned.length - 1;\n         while(i >= 0)\n         {\n            p = Projectile(this._waitingToBeCleaned[i]);\n            ++p.framesDead;\n            if(p.isReadyForCleanup())\n            {\n               last = this._waitingToBeCleaned.length - 1;\n               this._waitingToBeCleaned[i] = this._waitingToBeCleaned[last];\n               this._waitingToBeCleaned.pop();\n               if(game.battlefield.contains(p))\n               {\n                  game.battlefield.removeChild(p);\n               }\n               this._projectileMap[p.type].returnItem(p);\n            }\n            --i;\n         }\n      }\n''','swap-remove projectiles'),
])

